package com.carx.snowcontrol;
import android.app.*; import android.content.*; import android.graphics.PixelFormat; import android.os.*; import android.view.*; import android.widget.FrameLayout;
public final class FloatingService extends Service { private WindowManager wm; private FrameLayout host; private PiggyOverlayController pig; private WindowManager.LayoutParams lp;
 public void onCreate(){super.onCreate(); String ch="snow_slider"; if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(ch,"CarX PigHax UI",NotificationManager.IMPORTANCE_LOW); ((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);} Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,ch):new Notification.Builder(this); b.setContentTitle("CarX 控制面板").setContentText("PigHax 原生悬浮 UI 运行中").setSmallIcon(android.R.drawable.ic_menu_edit); startForeground(7822,b.build()); wm=(WindowManager)getSystemService(WINDOW_SERVICE); host=new FrameLayout(this); lp=new WindowManager.LayoutParams(-1,-1,Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE,WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT); lp.gravity=Gravity.TOP|Gravity.START; wm.addView(host,lp); PigHax.ensure(this); pig=new PiggyOverlayController(); pig.showFloatingWindow(this,host); }
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;} public void onDestroy(){try{if(host!=null)wm.removeView(host);}catch(Exception ignored){} super.onDestroy();} public IBinder onBind(Intent i){return null;} }
